39	/* =========================== 命名空间 =========================== */
40	const G = {
41	  canvas: null,
42	  ctx: null,
43	  W: 0, H: 0,
44	
45	  /* 游戏状态 */
46	  state: 'start',     // start | playing | dead
47	  score: 0,
48	  highScore: 0,
