50	  distance: 0,
51	  speed: 0,
52	  hearts: 3,
53	  invincible: 0,       // 剩余无敌帧数
54	
55	  /* 玩家 */
56	  player: null,
57	
58	  /* 对象池 */
59	  obstacles: [],
60	  coins: [],
61	  particles: [],
62	  powerups: [],
63	
64	  /* 输入 */
65	  keys: {},
66	  swipeStart: null,
67	  lastSwipe: '',
68	
69	  /* 屏幕震动 */
70	  shakeX: 0,
71	  shakeY: 0,
72	  shakeDuration: 0,
73	  flashAlpha: 0,
74	
75	  /* 世界参数 */
76	  vanishY: 0,          // 消失点 Y
77	  vanishX: 0,          // 消失点 X
78	  maxDist: 1200,        // 最大可视距离
79	  laneSpread: 0,       // 轨道底部扩散宽度
80	  groundY: 0,          // 玩家地面位置 Y（屏幕坐标）
81	
82	  /* 生成控制 */
83	  spawnTimer: 0,
84	  spawnInterval: 60,   // 初始帧间隔
85	  coinTimer: 0,
86	  laneCooldown: 0,     // 换道冷却帧数
87	
88	  /* 帧率 */
89	  lastTime: 0,
90	  deltaTime: 0,
91	  fps: 0,
92	  frameCount: 0,
93	  fpsFrameCount: 0,
94	  fpsTime: 0,
95	
96	  /* 离线画布 */
97	  offscreen: {},
98	
99	  /* 音效 */
100	  audioCtx: null,
101	  audioReady: false,
102	};
103	
104	/* =========================== 常量 =========================== */
105	const LANE_COUNT = 3;
106	const PLAYER_LANE = 1;     // 玩家初始在中间轨道 (0=左, 1=中, 2=右)
107	const MAX_HEARTS = 3;
108	const INVINCIBLE_FRAMES = 90;  // 1.5秒 @ 60fps
109	const BASE_SPEED = 1.2;
110	const MAX_SPEED = 3;
111	const SPEED_INC = 0.00025;      // 每帧加速量（更平缓）
112	const DISTANCE_PER_FRAME = 0.6; // 每帧距离增量（米）
113	const COIN_SCORE = 50;
114	const DISTANCE_SCORE = 1;       // 每米分数
115	
116	/* 玩家动作状态 */
117	const STATE_RUN = 'run';
118	const STATE_JUMP = 'jump';
119	const STATE_SLIDE = 'slide';
120	const STATE_HIT = 'hit';
121	
122	/* 障碍物类型 */
123	const OBS_LOW = 'low';       // 滑铲通过
124	const OBS_MID = 'mid';       // 跳跃通过
125	const OBS_HIGH = 'high';     // 必须换道
126	
127	/* 道具类型 */
128	const PUP_MAGNET = 'magnet';   // 磁铁：自动吸金币
129	const PUP_SHIELD = 'shield';   // 护盾：额外承受一次伤害
130	const PUP_2X = '2x';           // 双倍分数
131	
132	const POWERUP_DURATION = 480;  // 道具持续时间 8秒 @ 60fps
133	const MAGNET_RANGE = 1.5;      // 磁铁吸金币范围（轨道单位）
