135	/* =========================== 工具函数 =========================== */
136	function lerp(a, b, t) { return a + (b - a) * t; }
137	function clamp(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
138	function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
139	function randChoice(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
140	
141	/* =========================== Web Audio 音效系统 =========================== */
142	/** 初始化 AudioContext（需在首次用户交互后调用） */
143	function initAudio() {
144	  if (G.audioReady) return;
145	  try {
146	    G.audioCtx = new (window.AudioContext || window.webkitAudioContext)();
147	    G.audioReady = true;
148	  } catch(e) {
149	    G.audioReady = false;
150	  }
151	}
152	
153	/** 播放一个简单的合成音效 */
154	function playSound(freq, type, duration, vol, options) {
155	  if (!G.audioReady) return;
156	  const ctx = G.audioCtx;
157	  const opts = options || {};
158	  const now = ctx.currentTime;
159	
160	  const osc = ctx.createOscillator();
161	  const gain = ctx.createGain();
162	  osc.type = type || 'sine';
163	  osc.frequency.setValueAtTime(freq, now);
164	  if (opts.freqEnd) osc.frequency.linearRampToValueAtTime(opts.freqEnd, now + duration);
165	  gain.gain.setValueAtTime(vol || 0.15, now);
166	  gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
167	  osc.connect(gain);
168	  gain.connect(ctx.destination);
169	  osc.start(now);
170	  osc.stop(now + duration);
171	}
172	
173	/** 噪音发生器——用于滑铲、撞击等 */
174	function playNoise(duration, vol, filterFreq) {
175	  if (!G.audioReady) return;
176	  const ctx = G.audioCtx;
177	  const now = ctx.currentTime;
178	  const bufferSize = Math.floor(ctx.sampleRate * duration);
179	  const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
180	  const data = buffer.getChannelData(0);
181	  for (let i = 0; i < bufferSize; i++) {
182	    data[i] = (Math.random() * 2 - 1) * (1 - i / bufferSize); // 衰减包络
183	  }
184	  const source = ctx.createBufferSource();
185	  source.buffer = buffer;
186	  const gain = ctx.createGain();
187	  gain.gain.setValueAtTime(vol || 0.1, now);
188	  gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
189	
190	  let node = source;
191	  if (filterFreq) {
192	    const filter = ctx.createBiquadFilter();
193	    filter.type = 'lowpass';
194	    filter.frequency.setValueAtTime(filterFreq, now);
195	    source.connect(filter);
196	    node = filter;
197	  }
198	  node.connect(gain);
199	  gain.connect(ctx.destination);
200	  source.start(now);
201	  source.stop(now + duration);
202	}
203	
204	/* 各音效快捷函数 */
205	function sfxJump() {
206	  playSound(350, 'square', 0.15, 0.08, { freqEnd: 700 });
207	}
208	
209	function sfxSlide() {
210	  playNoise(0.12, 0.06, 800);
211	}
212	
213	function sfxCoin() {
214	  if (!G.audioReady) return;
215	  const ctx = G.audioCtx;
216	  const now = ctx.currentTime;
217	  [880, 1320].forEach((f, i) => {
218	    const osc = ctx.createOscillator();
219	    const gain = ctx.createGain();
220	    osc.type = 'square';
221	    osc.frequency.setValueAtTime(f, now + i * 0.06);
222	    gain.gain.setValueAtTime(0.06, now + i * 0.06);
223	    gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.06 + 0.1);
224	    osc.connect(gain);
225	    gain.connect(ctx.destination);
226	    osc.start(now + i * 0.06);
227	    osc.stop(now + i * 0.06 + 0.1);
228	  });
229	}
230	
231	function sfxHurt() {
232	  if (!G.audioReady) return;
233	  const ctx = G.audioCtx;
234	  const now = ctx.currentTime;
235	  /* 低频撞击 + 噪音 */
236	  const osc = ctx.createOscillator();
237	  const gain = ctx.createGain();
238	  osc.type = 'triangle';
239	  osc.frequency.setValueAtTime(120, now);
240	  osc.frequency.exponentialRampToValueAtTime(40, now + 0.2);
241	  gain.gain.setValueAtTime(0.15, now);
242	  gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
243	  osc.connect(gain);
244	  gain.connect(ctx.destination);
245	  osc.start(now);
246	  osc.stop(now + 0.2);
247	  playNoise(0.1, 0.08, 300);
248	}
249	
250	function sfxDeath() {
251	  if (!G.audioReady) return;
252	  const ctx = G.audioCtx;
253	  const now = ctx.currentTime;
254	  /* 下降音阶 */
255	  [400, 300, 200, 120].forEach((f, i) => {
256	    const osc = ctx.createOscillator();
257	    const gain = ctx.createGain();
258	    osc.type = 'sawtooth';
259	    osc.frequency.setValueAtTime(f, now + i * 0.12);
260	    gain.gain.setValueAtTime(0.1, now + i * 0.12);
261	    gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.12 + 0.15);
262	    osc.connect(gain);
263	    gain.connect(ctx.destination);
264	    osc.start(now + i * 0.12);
265	    osc.stop(now + i * 0.12 + 0.15);
266	  });
267	  playNoise(0.25, 0.12, 200);
268	}
269	
270	function sfxPowerup() {
271	  if (!G.audioReady) return;
272	  const ctx = G.audioCtx;
273	  const now = ctx.currentTime;
274	  /* 上行琶音 */
275	  [440, 554, 659, 880].forEach((f, i) => {
276	    const osc = ctx.createOscillator();
277	    const gain = ctx.createGain();
278	    osc.type = 'sine';
279	    osc.frequency.setValueAtTime(f, now + i * 0.08);
280	    gain.gain.setValueAtTime(0.08, now + i * 0.08);
281	    gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.08 + 0.15);
282	    osc.connect(gain);
283	    gain.connect(ctx.destination);
284	    osc.start(now + i * 0.08);
285	    osc.stop(now + i * 0.08 + 0.15);
286	  });
287	}
288	
289	/* 屏幕坐标：根据世界深度计算 screenY 和缩放比例 */
290	function worldToScreen(dist) {
291	  /* dist: 0 = 玩家脚下, maxDist = 地平线 */
292	  /* 允许负距离——障碍物穿过玩家后继续向屏幕下方移动 */
293	  const raw = Math.max(dist / G.maxDist, -0.35);
294	  const t = 1 - raw; // t > 1 表示障碍物已在玩家身后
295	  const screenY = lerp(G.vanishY, G.groundY, clamp(t, 0, 1.35));
296	  const scale = lerp(0.3, 1.0, clamp(t, 0, 1.35));
297	  return { y: screenY, scale };
298	}
299	
300	/* 轨道 X 坐标：根据深度 + 轨道索引计算 screenX */
301	function laneX(laneIdx, dist) {
302	  const t = 1 - clamp(dist / G.maxDist, 0, 1);
303	  const spread = lerp(0, G.laneSpread, t);
304	  const centerX = G.vanishX;
305	  return centerX + (laneIdx - 1) * spread;
306	}
307	
308	/* =========================== 初始化 =========================== */
309	function init() {
310	  G.canvas = document.getElementById('game');
311	  G.ctx = G.canvas.getContext('2d', { alpha: false });
312	  resize();
313	  window.addEventListener('resize', resize);
314	
315	  /* 加载最高分 */
316	  try {
317	    G.highScore = parseInt(localStorage.getItem('railRunner_highScore')) || 0;
318	  } catch(e) { G.highScore = 0; }
319	
320	  /* 输入：键盘 */
321	  window.addEventListener('keydown', e => {
322	    G.keys[e.key] = true;
323	    if (e.key === ' ' || e.key === 'ArrowUp' || e.key === 'ArrowDown') {
324	      e.preventDefault();
325	    }
326	    if (G.state === 'start' && e.key === ' ') startGame();
327	    if (G.state === 'dead' && e.key === ' ') restartGame();
328	  });
329	  window.addEventListener('keyup', e => { G.keys[e.key] = false; });
330	
331	  /* 输入：触屏 */
332	  G.canvas.addEventListener('touchstart', e => {
333	    e.preventDefault();
334	    if (G.state === 'start') { startGame(); return; }
335	    if (G.state === 'dead') { restartGame(); return; }
336	    const t = e.touches[0];
337	    G.swipeStart = { x: t.clientX, y: t.clientY, time: Date.now() };
338	  }, { passive: false });
339	
340	  G.canvas.addEventListener('touchend', e => {
341	    if (!G.swipeStart) return;
342	    const t = e.changedTouches[0];
343	    const dx = t.clientX - G.swipeStart.x;
344	    const dy = t.clientY - G.swipeStart.y;
345	    const dt = Date.now() - G.swipeStart.time;
346	    const absDx = Math.abs(dx), absDy = Math.abs(dy);
347	
348	    if (Math.max(absDx, absDy) < 20) return; // 太小忽略
349	
350	    if (absDx > absDy) {
351	      G.lastSwipe = dx > 0 ? 'right' : 'left';
352	    } else {
353	      G.lastSwipe = dy > 0 ? 'down' : 'up';
354	    }
355	    G.swipeStart = null;
356	  });
357	
358	  /* 玩家 */
359	  G.player = createPlayer();
360	
361	  /* 预渲染 */
362	  preRenderAssets();
363	
364	  /* 启动循环 */
365	  G.lastTime = performance.now();
366	  requestAnimationFrame(gameLoop);
367	}
368	
369	function resize() {
370	  const container = document.getElementById('game-container');
371	  const rect = container.getBoundingClientRect();
372	  const dpr = Math.min(window.devicePixelRatio || 1, 2); // 限制像素比
373	  G.W = rect.width;
374	  G.H = rect.height;
375	  G.canvas.width = G.W * dpr;
376	  G.canvas.height = G.H * dpr;
377	  G.canvas.style.width = G.W + 'px';
378	  G.canvas.style.height = G.H + 'px';
379	  G.ctx.setTransform(1, 0, 0, 1, 0, 0);
380	  G.ctx.scale(dpr, dpr);
381	
382	  /* 重新计算透视参数 */
383	  G.vanishX = G.W * 0.5;
384	  G.vanishY = G.H * 0.28;
385	  G.groundY = G.H * 0.88;
386	  G.laneSpread = G.W * 0.18;
387	
388	  /* 预渲染需要 resize */
389	  preRenderAssets();
390	}
391	
392	/* =========================== 预渲染资源 =========================== */
393	function preRenderAssets() {
394	  /* --- 天空渐变背景 --- */
395	  const skyCanvas = document.createElement('canvas');
396	  skyCanvas.width = G.W;
397	  skyCanvas.height = G.H;
398	  const skyCtx = skyCanvas.getContext('2d');
399	  const grad = skyCtx.createLinearGradient(0, 0, 0, G.vanishY + 40);
400	  grad.addColorStop(0, '#1a1a4e');
401	  grad.addColorStop(0.5, '#2d4a8e');
402	  grad.addColorStop(1, '#5ba3d9');
403	  skyCtx.fillStyle = grad;
404	  skyCtx.fillRect(0, 0, G.W, G.H);
405	  /* 云层 */
406	  skyCtx.fillStyle = 'rgba(255,255,255,0.08)';
407	  for (let ci = 0; ci < 8; ci++) {
408	    const cx = Math.random() * G.W;
409	    const cy = Math.random() * G.vanishY * 0.7;
410	    const cw = 60 + Math.random() * 120;
411	    skyCtx.beginPath();
412	    skyCtx.ellipse(cx, cy, cw, 12 + Math.random() * 10, 0, 0, Math.PI * 2);
413	    skyCtx.fill();
414	    skyCtx.beginPath();
415	    skyCtx.ellipse(cx + cw*0.3, cy - 8, cw*0.6, 10 + Math.random() * 8, 0, 0, Math.PI * 2);
416	    skyCtx.fill();
417	  }
418	  G.offscreen.sky = skyCanvas;
419	
420	  /* --- 城市天际线（远景） --- */
421	  const cityCanvas = document.createElement('canvas');
422	  cityCanvas.width = G.W * 3; // 宽于屏幕用于视差滚动
423	  cityCanvas.height = G.H * 0.25;
424	  const cityCtx = cityCanvas.getContext('2d');
425	  /* 建筑剪影 */
426	  cityCtx.fillStyle = '#1a1a3e';
427	  const buildings = [];
428	  let bx = 0;
429	  while (bx < cityCanvas.width) {
430	    const bw = randInt(30, 100);
431	    const bh = randInt(40, cityCanvas.height * 0.85);
432	    buildings.push({ x: bx, w: bw, h: bh });
