518	/* =========================== 精灵绘制 =========================== */
519	/* 涂鸦标签 -- 在指定位置绘制随机涂鸦 */
520	function drawGraffitiTag(ctx, x, y, w, h) {
521	  const colors = ['#ff3366','#ff6600','#ffcc00','#33ff66','#33ccff','#ff33cc','#aaff00','#ff0066'];
522	  const bgColors = ['#1a1a2e','#2a1a4e','#1a3a2e','#3a1a2e','#2a2a4e'];
523	
524	  /* 背景色块（涂鸦底板） */
525	  const bg = randChoice(bgColors);
526	  ctx.fillStyle = bg;
527	  ctx.fillRect(x, y, w, h);
528	  ctx.strokeStyle = 'rgba(255,255,255,0.2)';
529	  ctx.lineWidth = 1;
530	  ctx.strokeRect(x, y, w, h);
531	
532	  /* 涂鸦文字/图案 */
533	  const tagColor = randChoice(colors);
534	  ctx.fillStyle = tagColor;
535	
536	  /* 随机选择涂鸦风格 */
537	  const style = randInt(0, 4);
538	  const cx = x + w/2, cy = y + h/2;
539	
540	  if (style === 0) {
541	    /* 气泡字体风格 -- 重叠的圆 */
542	    ctx.globalAlpha = 0.8;
543	    for (let i = 0; i < 5; i++) {
544	      const bx = x + 10 + Math.random() * (w - 20);
545	      const by = y + 10 + Math.random() * (h - 20);
546	      const br = 8 + Math.random() * 15;
547	      ctx.beginPath(); ctx.arc(bx, by, br, 0, Math.PI*2); ctx.fill();
548	    }
549	    ctx.globalAlpha = 1;
550	  } else if (style === 1) {
551	    /* 喷漆线条 -- 粗犷的水平条纹 */
552	    ctx.lineWidth = 4 + Math.random() * 8;
553	    ctx.strokeStyle = tagColor;
554	    for (let i = 0; i < 4; i++) {
555	      ctx.beginPath();
556	      const ly = y + 10 + i * h/4;
557	      ctx.moveTo(x + 5, ly);
558	      ctx.lineTo(x + w - 5, ly + (Math.random()-0.5)*10);
559	      ctx.stroke();
560	    }
561	  } else if (style === 2) {
562	    /* 箭头/三角形涂鸦 */
563	    ctx.beginPath();
564	    ctx.moveTo(cx, cy - h*0.3);
565	    ctx.lineTo(cx + w*0.35, cy + h*0.25);
566	    ctx.lineTo(cx - w*0.35, cy + h*0.25);
567	    ctx.closePath(); ctx.fill();
568	    /* 内圈 */
569	    ctx.fillStyle = bg;
570	    ctx.beginPath(); ctx.arc(cx, cy + h*0.05, w*0.12, 0, Math.PI*2); ctx.fill();
571	  } else if (style === 3) {
572	    /* 星形/爆炸 */
573	    const spikes = randInt(5, 8);
574	    ctx.beginPath();
575	    for (let i = 0; i < spikes * 2; i++) {
576	      const r = i % 2 === 0 ? Math.min(w,h)*0.4 : Math.min(w,h)*0.15;
577	      const angle = (i / (spikes * 2)) * Math.PI * 2 - Math.PI/2;
578	      const px = cx + Math.cos(angle) * r;
579	      const py = cy + Math.sin(angle) * r;
580	      if (i === 0) ctx.moveTo(px, py);
581	      else ctx.lineTo(px, py);
582	    }
583	    ctx.closePath(); ctx.fill();
584	  } else {
585	    /* 滴落风格 -- 垂直线条 + 圆点 */
586	    const drops = randInt(3, 7);
587	    for (let i = 0; i < drops; i++) {
588	      const dx = x + w * (0.2 + Math.random() * 0.6);
589	      ctx.beginPath();
590	      ctx.moveTo(dx, y + 5);
591	      ctx.lineTo(dx, y + h * (0.3 + Math.random() * 0.5));
592	      ctx.lineWidth = 3 + Math.random() * 4;
593	      ctx.strokeStyle = randChoice(colors);
594	      ctx.stroke();
595	      ctx.beginPath();
596	      ctx.arc(dx, y + h * (0.3 + Math.random() * 0.5), 3 + Math.random()*5, 0, Math.PI*2);
597	      ctx.fillStyle = randChoice(colors);
598	      ctx.fill();
599	    }
600	  }
601	
602	  /* 白色高光/溅洒点 */
603	  ctx.fillStyle = 'rgba(255,255,255,0.4)';
604	  for (let i = 0; i < 8; i++) {
605	    const sx = x + Math.random() * w;
606	    const sy = y + Math.random() * h;
607	    ctx.beginPath(); ctx.arc(sx, sy, 1 + Math.random()*2, 0, Math.PI*2); ctx.fill();
608	  }
609	}
