765	/* 肢体绘制：从原点出发，第一段角度 a1 长度 l1，第二段角度 a1+a2 长度 l2 */
766	function drawLimb(ctx, ox, oy, a1, a2, l1, l2, c1, c2, w1, w2) {
767	  const jx = ox + Math.sin(a1) * l1 * 0.22;
768	  const jy = oy + Math.cos(a1) * l1;
769	  thickLine(ctx, ox, oy, jx, jy, w1, c1);
770	  const ex = jx + Math.sin(a1 + a2) * l2 * 0.22;
771	  const ey = jy + Math.cos(a1 + a2) * l2;
772	  thickLine(ctx, jx, jy, ex, ey, w2, c2);
773	  /* 关节 */
774	  ctx.fillStyle = c2;
775	  ctx.beginPath(); ctx.arc(jx, jy, w2 * 0.45, 0, Math.PI * 2); ctx.fill();
776	}
777	
778	function footPos(ox, oy, a1, a2, l1, l2) {
779	  const jx = ox + Math.sin(a1) * l1 * 0.22;
780	  const jy = oy + Math.cos(a1) * l1;
781	  return {
782	    x: jx + Math.sin(a1 + a2) * l2 * 0.22,
783	    y: jy + Math.cos(a1 + a2) * l2,
784	    ang: a1 + a2
785	  };
786	}
787	
788	function armPos(ox, oy, a1, a2, l1, l2) {
789	  const jx = ox + Math.sin(a1) * l1 * 0.30;
790	  const jy = oy + Math.cos(a1) * l1;
791	  return {
792	    x: jx + Math.sin(a1 + a2) * l2 * 0.28,
793	    y: jy + Math.cos(a1 + a2) * l2
794	  };
795	}
796	
797	function thickLine(ctx, x1, y1, x2, y2, w, c) {
798	  const dx = x2 - x1, dy = y2 - y1, len = Math.sqrt(dx * dx + dy * dy);
799	  if (len < 0.3) return;
800	  ctx.save(); ctx.translate(x1, y1); ctx.rotate(Math.atan2(dy, dx));
801	  ctx.fillStyle = c;
802	  const r = w / 2;
803	  ctx.beginPath();
804	  ctx.moveTo(r, -r); ctx.lineTo(len - r, -r);
805	  ctx.quadraticCurveTo(len, -r, len, 0);
806	  ctx.quadraticCurveTo(len, r, len - r, r);
807	  ctx.lineTo(r, r);
808	  ctx.quadraticCurveTo(0, r, 0, 0);
809	  ctx.quadraticCurveTo(0, -r, r, -r);
810	  ctx.fill();
811	  ctx.restore();
812	}
