814	function drawShoe(ctx, x, y, ang) {
815	  ctx.save(); ctx.translate(x, y); ctx.rotate(ang + 0.15);
816	  ctx.fillStyle = SP.shoe;
817	  ctx.beginPath();
818	  ctx.moveTo(-4, -2); ctx.lineTo(7, -2);
819	  ctx.quadraticCurveTo(9, 0, 7, 2.5); ctx.lineTo(-4, 2.5);
820	  ctx.quadraticCurveTo(-6, 0, -4, -2);
821	  ctx.fill();
822	  ctx.fillStyle = SP.sole; ctx.fillRect(-4, 1.5, 11, 2.5);
823	  ctx.fillStyle = SP.shoeA; ctx.fillRect(1, 1.5, 1.5, 2.5);
824	  ctx.restore();
825	}
