827	/* 8帧跑步循环定义
828	   每帧角度参数：hipA=大腿角(0=垂直向下,正=前摆), kneeA=膝角(正=弯曲)
829	   shldA=上臂角(0=垂直向下,正=前摆), elbowA=肘角(正=弯曲)
830	   跑步循环阶段：接触(contact)→下沉(down)→经过(passing)→蹬起(up)→接触(另一脚) */
831	const RUN_POSES = [
