953	/* =========================== 对象池 =========================== */
954	function poolGet(pool, factory) {
955	  for (let i = 0; i < pool.length; i++) {
956	    if (!pool[i].active) { pool[i].active = true; return pool[i]; }
957	  }
958	  const obj = factory();
959	  obj.active = true;
960	  pool.push(obj);
961	  return obj;
962	}
963	
964	function poolReleaseAll(pool) {
965	  for (let i = 0; i < pool.length; i++) pool[i].active = false;
966	}
