1114	  let slide = false;
1115	
1116	  /* 键盘 */
1117	  if (G.keys['ArrowLeft'] || G.keys['a'] || G.keys['A']) moveLR = -1;
1118	  if (G.keys['ArrowRight'] || G.keys['d'] || G.keys['D']) moveLR = 1;
1119	  if (G.keys['ArrowUp'] || G.keys['w'] || G.keys['W']) jump = true;
1120	  if (G.keys['ArrowDown'] || G.keys['s'] || G.keys['S']) slide = true;
1121	
1122	  /* 触屏 */
1123	  if (G.lastSwipe === 'left') { moveLR = -1; G.lastSwipe = ''; }
1124	  if (G.lastSwipe === 'right') { moveLR = 1; G.lastSwipe = ''; }
1125	  if (G.lastSwipe === 'up') { jump = true; G.lastSwipe = ''; }
1126	  if (G.lastSwipe === 'down') { slide = true; G.lastSwipe = ''; }
1127	
1128	  const p = G.player;
1129	  /* 换道——加冷却防止连按瞬移 */
1130	  if (G.laneCooldown > 0) G.laneCooldown--;
1131	  if (moveLR !== 0 && p.state !== STATE_SLIDE && G.laneCooldown <= 0) {
1132	    p.targetLane = clamp(p.targetLane + moveLR, 0, LANE_COUNT - 1);
1133	    G.laneCooldown = 8; // ~0.13秒冷却
1134	  }
1135	  /* 跳跃 */
1136	  if (jump && p.state === STATE_RUN) {
1137	    p.state = STATE_JUMP;
1138	    p.stateTimer = 150;
1139	    p.jumpVel = -3;
1140	    sfxJump();
