1156	/* =========================== 游戏更新 =========================== */
1157	function update() {
1158	  if (G.state !== 'playing') return;
1159	
1160	  const p = G.player;
1161	
1162	  /* --- 速度 & 距离 --- */
1163	  G.speed = Math.min(G.speed + SPEED_INC, MAX_SPEED);
1164	  G.distance += G.speed * DISTANCE_PER_FRAME;
1165	  G.score = Math.floor(G.distance * DISTANCE_SCORE * G.player.scoreMultiplier) + G.coinScore;
1166	
1167	  /* --- 无敌计时 --- */
1168	  if (G.invincible > 0) G.invincible--;
1169	
1170	  /* 屏幕震动衰减 */
1171	  if (G.shakeDuration > 0) {
1172	    G.shakeDuration--;
1173	    G.shakeX *= 0.8;
1174	    G.shakeY *= 0.8;
1175	  } else {
1176	    G.shakeX = 0; G.shakeY = 0;
1177	  }
1178	  /* 红色闪屏衰减 */
1179	  if (G.flashAlpha > 0) G.flashAlpha -= 0.02;
1180	
1181	  /* --- 轨道平滑切换 --- */
1182	  p.lane = lerp(p.lane, p.targetLane, 0.25);
1183	
1184	  /* --- 玩家状态 --- */
1185	  if (p.state === STATE_JUMP) {
1186	    p.stateTimer--;
1187	    if (p.stateTimer <= 0) {
1188	      p.state = STATE_RUN;
1189	      p.stateTimer = 0;
1190	    }
1191	  } else if (p.state === STATE_SLIDE) {
1192	    p.stateTimer--;
1193	    if (p.stateTimer <= 0) {
1194	      p.state = STATE_RUN;
1195	      p.stateTimer = 0;
1196	    }
1197	  } else if (p.state === STATE_HIT) {
1198	    p.stateTimer--;
1199	    if (p.stateTimer <= 0) {
1200	      p.state = STATE_RUN;
1201	    }
1202	  }
1203	
1204	  /* 庆祝动作计时 */
1205	  if (p.celebrateTimer > 0) {
1206	    p.celebrateTimer--;
1207	    if (p.celebrateTimer <= 0) p.celebrateType = null;
1208	  }
1209	
1210	  /* --- 动画帧 --- */
1211	  p.animTimer++;
1212	  if (p.animTimer > 8) {
1213	    p.animTimer = 0;
1214	    p.animFrame = (p.animFrame + 1) % 4;
1215	  }
1216	
1217	  /* --- 移动障碍物 --- */
1218	  for (let i = 0; i < G.obstacles.length; i++) {
1219	    const obs = G.obstacles[i];
1220	    if (!obs.active) continue;
1221	    obs.dist -= G.speed;
1222	    if (obs.dist < -400) { obs.active = false; continue; }
1223	    /* 碰撞检测（仅当障碍物接近玩家时） */
1224	    if (!obs.passed && obs.dist < 18 && obs.dist > -5) {
1225	      if (sameLane(obs)) {
1226	        /* 低障碍：滑铲可通过 */
1227	        if (obs.type === OBS_LOW && p.state === STATE_SLIDE) continue;
1228	        /* 中障碍：跳跃可通过 */
1229	        if (obs.type === OBS_MID && p.state === STATE_JUMP) continue;
1230	        /* 高障碍：必须换道——同轨即受伤 */
1231	        hurtPlayer(1);
1232	      }
1233	    }
1234	    /* 障碍物成功穿过——触发庆祝动作 */
1235	    if (!obs.passed && obs.dist < -5 && sameLane(obs) && p.celebrateTimer <= 0) {
1236	      obs.passed = true;
1237	      if (obs.type === OBS_MID && p.state === STATE_JUMP) {
1238	        p.celebrateType = 'lookback';
1239	        p.celebrateTimer = 40;
1240	      } else if (obs.type === OBS_LOW && p.state === STATE_SLIDE) {
1241	        p.celebrateType = 'kick';
1242	        p.celebrateTimer = 35;
1243	      }
1244	    }
1245	    if (obs.dist < -5) obs.passed = true;
1246	  }
1247	
1248	  /* --- 移动金币 --- */
1249	  for (let i = 0; i < G.coins.length; i++) {
1250	    const coin = G.coins[i];
1251	    if (!coin.active) continue;
1252	    coin.dist -= G.speed;
1253	    if (coin.dist < -400) { coin.active = false; continue; }
1254	    /* 收集检测 */
1255	    if (!coin.collected && coin.dist < 28 && coin.dist > -18 && Math.abs(coin.lane - p.lane) < 0.85) {
