1265	        pt.x = sx + (Math.random()-0.5)*20;
1266	        pt.y = s.y + (Math.random()-0.5)*20;
1267	        pt.vx = (Math.random()-0.5)*4;
1268	        pt.vy = (Math.random()-0.5)*4 - 2;
1269	        pt.life = randInt(10, 25);
1270	        pt.maxLife = pt.life;
1271	        pt.color = randChoice(['#ffdd44','#ffaa00','#ffe680','#fff']);
