1744	  ctx.shadowBlur = 0;
1745	  /* 图标（简化版用字母） */
1746	  ctx.fillStyle = pu.type === PUP_MAGNET ? '#ff44ff' : pu.type === PUP_SHIELD ? '#44aaff' : '#ffaa00';
1747	  ctx.font = `bold ${Math.floor(14*scale)}px "Segoe UI","PingFang SC",sans-serif`;
1748	  ctx.textAlign = 'center';
1749	  ctx.textBaseline = 'middle';
1750	  const ico = pu.type === PUP_MAGNET ? 'M' : pu.type === PUP_SHIELD ? 'S' : 'x2';
1751	  ctx.fillText(ico, 0, 0);
1752	  ctx.restore();
1753	}
1754	/* =========================== 绘制玩家 =========================== */
1755	function drawPlayer(ctx) {
1756	  const p = G.player;
1757	  const sprites = G.offscreen.player;
1758	  if (!sprites) return;
1759	  ctx.save();
1760	  ctx.translate(p.x, p.y);
1761	
1762	  /* 无敌闪烁 */
1763	  let alpha = 1;
1764	  if (G.invincible > 0 && Math.floor(G.invincible / 4) % 2 === 0) {
1765	    alpha = 0.35;
1766	  }
1767	
1768	  /* 阴影 */
1769	  ctx.fillStyle = 'rgba(0,0,0,0.25)';
1770	  ctx.beginPath();
1771	  ctx.ellipse(0, 12, 20, 7, 0, 0, Math.PI * 2);
1772	  ctx.fill();
1773	
1774	  /* 选择精灵帧 */
1775	  let frame = sprites.run[0]; // 默认第一帧
1776	  const SW = 80, SH = 100;
1777	
1778	  if (p.state === STATE_RUN) {
1779	    /* 庆祝动画 */
1780	    if (p.celebrateTimer > 0 && p.celebrateType) {
1781	      if (p.celebrateType === 'lookback') {
1782	        frame = sprites.lookback;
1783	      } else if (p.celebrateType === 'kick') {
1784	        frame = p.celebrateTimer > 15 ? sprites.kick : sprites.run[Math.floor(G.frameCount / 8) % 8];
1785	      }
1786	    } else {
1787	      /* 8帧跑步循环 ~7.5fps */
1788	      frame = sprites.run[Math.floor(G.frameCount / 8) % 8];
1789	    }
1790	  } else if (p.state === STATE_JUMP) {
1791	    frame = sprites.jump;
1792	  } else if (p.state === STATE_SLIDE) {
1793	    frame = sprites.slide;
1794	  } else if (p.state === STATE_HIT) {
1795	    frame = sprites.hit;
1796	  }
1797	
1798	  /* 绘制精灵（居中，底部对齐到地面） */
1799	  const sx = -SW / 2;
1800	  const sy = -SH + 8; // 脚底略低于 p.y
1801	  if (alpha < 1) ctx.globalAlpha = alpha;
1802	  ctx.drawImage(frame, sx, sy);
1803	  if (alpha < 1) ctx.globalAlpha = 1;
1804	
1805	  ctx.restore();
1806	}
1807	
1808	/* =========================== HUD =========================== */
1809	function drawHUD(ctx) {
1810	  if (G.state !== 'playing' && G.state !== 'dead') return;
1811	
1812	  /* 左上——血量 */
1813	  const heartSize = 18;
1814	  for (let i = 0; i < MAX_HEARTS; i++) {
1815	    const hx = 16 + i * (heartSize + 6);
1816	    const hy = 16;
1817	    if (i < G.hearts) {
1818	      /* 满血——红色心 */
1819	      drawHeart(ctx, hx, hy, heartSize, '#e94560');
1820	    } else {
1821	      /* 空血——灰色 */
1822	      drawHeart(ctx, hx, hy, heartSize, '#444');
1823	    }
1824	  }
1825	
1826	  /* 顶部居中——分数 */
1827	  ctx.fillStyle = '#fff';
1828	  ctx.font = 'bold 28px "Segoe UI","PingFang SC",sans-serif';
1829	  ctx.textAlign = 'center';
1830	  ctx.shadowColor = 'rgba(0,0,0,0.6)';
1831	  ctx.shadowBlur = 4;
1832	  ctx.fillText(Math.floor(G.score), G.W / 2, 40);
1833	  ctx.shadowBlur = 0;
1834	
1835	  /* 右上——速度指示 */
1836	  const speedPct = Math.floor((G.speed - BASE_SPEED) / (MAX_SPEED - BASE_SPEED) * 100);
1837	  ctx.fillStyle = speedPct > 70 ? '#ff6644' : '#aaccff';
1838	  ctx.font = '12px "Segoe UI","PingFang SC",sans-serif';
1839	  ctx.textAlign = 'right';
1840	  ctx.fillText('速度 ' + speedPct + '%', G.W - 14, 28);
1841	
1842	  /* DEBUG：障碍物/金币统计 */
1843	  let activeObs = 0, activeCoins = 0;
1844	  for (let i = 0; i < G.obstacles.length; i++) if (G.obstacles[i].active) activeObs++;
1845	  for (let i = 0; i < G.coins.length; i++) if (G.coins[i].active) activeCoins++;
1846	  ctx.fillStyle = '#0f0';
1847	  ctx.font = '11px monospace';
1848	  ctx.textAlign = 'left';
1849	  ctx.fillText('DEBUG obs:' + activeObs + ' coins:' + activeCoins + ' dist:' + Math.floor(G.distance) + 'm spawn:' + Math.floor(G.spawnTimer) + '/' + Math.floor(G.spawnInterval/(G.speed/BASE_SPEED)), 12, G.H - 10);
1850	
1851	  /* 道具指示器 */
1852	  const pu = G.player;
1853	  if (pu.activePowerup || pu.hasShield) {
1854	    const puy = 60;
1855	    /* 护盾 */
1856	    if (pu.hasShield) {
1857	      ctx.fillStyle = '#44aaff';
1858	      ctx.font = 'bold 14px "Segoe UI","PingFang SC",sans-serif';
1859	      ctx.textAlign = 'right';
1860	      ctx.fillText('护盾', G.W - 14, puy);
1861	    }
1862	    /* 活动道具计时条 */
1863	    if (pu.activePowerup) {
1864	      const barW = 80, barH = 6;
1865	      const barX = G.W - 14 - barW, barY = puy + 4;
1866	      const pct = pu.powerupTimer / POWERUP_DURATION;
1867	      ctx.fillStyle = 'rgba(255,255,255,0.2)';
1868	      ctx.fillRect(barX, barY, barW, barH);
1869	      const barColor = pu.activePowerup === PUP_MAGNET ? '#ff44ff' :
1870	                       pu.activePowerup === PUP_2X ? '#ffdd00' : '#44aaff';
1871	      ctx.fillStyle = barColor;
1872	      ctx.fillRect(barX, barY, barW * pct, barH);
1873	      /* 标签 */
1874	      const label = pu.activePowerup === PUP_MAGNET ? '磁铁' : '2x分数';
1875	      ctx.fillStyle = '#fff';
1876	      ctx.font = 'bold 12px "Segoe UI","PingFang SC",sans-serif';
1877	      ctx.textAlign = 'right';
1878	      ctx.fillText(label, G.W - 14, puy);
1879	    }
1880	  }
1881	}
1882	
1883	function drawHeart(ctx, x, y, size, color) {
1884	  ctx.fillStyle = color;
1885	  ctx.beginPath();
1886	  const s = size / 20;
1887	  ctx.moveTo(x, y + size * 0.35);
1888	  /* 左半 */
1889	  ctx.bezierCurveTo(x, y + size*0.15, x - size*0.45, y - size*0.15, x - size*0.45, y + size*0.25);
1890	  ctx.bezierCurveTo(x - size*0.45, y + size*0.6, x, y + size*0.8, x, y + size);
1891	  /* 右半 */
1892	  ctx.bezierCurveTo(x, y + size*0.8, x + size*0.45, y + size*0.6, x + size*0.45, y + size*0.25);
1893	  ctx.bezierCurveTo(x + size*0.45, y - size*0.15, x, y + size*0.15, x, y + size*0.35);
1894	  ctx.fill();
1895	}
1896	
1897	/* =========================== 界面 =========================== */
1898	function drawStartScreen(ctx) {
1899	  /* 半透明遮罩 */
1900	  ctx.fillStyle = 'rgba(0,0,0,0.55)';
1901	  ctx.fillRect(0, 0, G.W, G.H);
1902	
1903	  /* 标题 */
1904	  ctx.fillStyle = '#fff';
1905	  ctx.font = 'bold 48px "Segoe UI","PingFang SC",sans-serif';
1906	  ctx.textAlign = 'center';
1907	  ctx.shadowColor = '#e94560';
1908	  ctx.shadowBlur = 20;
1909	  ctx.fillText('轨道跑者', G.W/2, G.H * 0.3);
1910	  ctx.shadowBlur = 0;
1911	
1912	  ctx.fillStyle = '#ffcc00';
1913	  ctx.font = 'bold 18px "Segoe UI","PingFang SC",sans-serif';
1914	  ctx.fillText('RAIL RUNNER', G.W/2, G.H * 0.3 + 40);
1915	
1916	  /* 操作说明 */
1917	  ctx.fillStyle = '#ddd';
1918	  ctx.font = '16px "Segoe UI","PingFang SC",sans-serif';
1919	  const instructions = [
1920	    '← →  切换轨道',
1921	    '↑  跳跃  |  ↓  滑铲',
1922	    '空格键  开始 / 重来',
1923	  ];
1924	  instructions.forEach((txt, i) => {
1925	    ctx.fillText(txt, G.W/2, G.H * 0.55 + i * 28);
1926	  });
1927	
1928	  /* 最高分 */
1929	  if (G.highScore > 0) {
1930	    ctx.fillStyle = '#ffdd44';
1931	    ctx.font = 'bold 20px "Segoe UI","PingFang SC",sans-serif';
1932	    ctx.fillText('最高分: ' + G.highScore, G.W/2, G.H * 0.74);
1933	  }
1934	
1935	  /* 提示 */
1936	  const alpha = 0.5 + 0.5 * Math.sin(G.frameCount * 0.05);
1937	  ctx.fillStyle = `rgba(255,255,255,${alpha})`;
1938	  ctx.font = '18px "Segoe UI","PingFang SC",sans-serif';
1939	  ctx.fillText('点击屏幕 或 按空格键 开始', G.W/2, G.H * 0.85);
1940	}
1941	
1942	function drawDeathScreen(ctx) {
1943	  /* 半透明遮罩 */
1944	  ctx.fillStyle = 'rgba(0,0,0,0.6)';
1945	  ctx.fillRect(0, 0, G.W, G.H);
1946	
1947	  /* 得分面板背景 */
1948	  const panelW = G.W * 0.7;
1949	  const panelH = G.H * 0.35;
1950	  const panelX = (G.W - panelW) / 2;
1951	  const panelY = G.H * 0.25;
1952	  ctx.fillStyle = 'rgba(20,20,40,0.9)';
1953	  ctx.strokeStyle = '#e94560';
1954	  ctx.lineWidth = 2;
1955	  roundRect(ctx, panelX, panelY, panelW, panelH, 16);
1956	  ctx.fill();
1957	  ctx.stroke();
1958	
1959	  /* 标题 */
1960	  ctx.fillStyle = '#e94560';
1961	  ctx.font = 'bold 28px "Segoe UI","PingFang SC",sans-serif';
1962	  ctx.textAlign = 'center';
1963	  ctx.fillText('游戏结束', G.W/2, panelY + 45);
1964	
1965	  /* 本次得分 */
1966	  ctx.fillStyle = '#fff';
1967	  ctx.font = 'bold 24px "Segoe UI","PingFang SC",sans-serif';
1968	  ctx.fillText('得分: ' + Math.floor(G.score), G.W/2, panelY + 80);
1969	
1970	  /* 距离 */
1971	  ctx.fillStyle = '#aaa';
1972	  ctx.font = '16px "Segoe UI","PingFang SC",sans-serif';
1973	  ctx.fillText('距离: ' + Math.floor(G.distance) + ' 米', G.W/2, panelY + 108);
1974	
1975	  /* 最高分 */
1976	  const isNew = G.score >= G.highScore && G.highScore > 0;
1977	  ctx.fillStyle = isNew ? '#ffdd44' : '#aaa';
1978	  ctx.font = 'bold 18px "Segoe UI","PingFang SC",sans-serif';
1979	  ctx.fillText((isNew ? '🎉 新纪录！' : '最高分: ') + G.highScore, G.W/2, panelY + 135);
1980	
1981	  /* 重来提示 */
1982	  const alpha = 0.5 + 0.5 * Math.sin(G.frameCount * 0.06);
1983	  ctx.fillStyle = `rgba(255,255,255,${alpha})`;
1984	  ctx.font = '18px "Segoe UI","PingFang SC",sans-serif';
1985	  ctx.fillText('点击屏幕 或 按空格键 重来', G.W/2, panelY + panelH + 40);
1986	}
1987	
1988	function roundRect(ctx, x, y, w, h, r) {
1989	  ctx.beginPath();
1990	  ctx.moveTo(x + r, y);
1991	  ctx.lineTo(x + w - r, y);
1992	  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
1993	  ctx.lineTo(x + w, y + h - r);
1994	  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
1995	  ctx.lineTo(x + r, y + h);
1996	  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
1997	  ctx.lineTo(x, y + r);
1998	  ctx.quadraticCurveTo(x, y, x + r, y);
1999	  ctx.closePath();
2000	}
2001	
2002	/* =========================== 游戏主循环 =========================== */
2003	function gameLoop(timestamp) {
2004	  G.deltaTime = timestamp - G.lastTime;
2005	  G.lastTime = timestamp;
2006	
2007	  /* FPS 计算 */
2008	  G.frameCount++;
2009	  G.fpsFrameCount++;
2010	  G.fpsTime += G.deltaTime;
2011	  if (G.fpsTime >= 1000) {
2012	    G.fps = G.fpsFrameCount;
2013	    G.fpsFrameCount = 0;
2014	    G.fpsTime = 0;
2015	  }
2016	
2017	  processInput();
2018	  update();
2019	  render();
2020	  requestAnimationFrame(gameLoop);
2021	}
2022	
2023	/* =========================== 启动 =========================== */
2024	init();
2025	</script>
2026	</body>
2027	</html>
2028

